def append_json(path: Path, items):
    raw = path.read_text(encoding='utf-8')
    pos = raw.rfind(']')
    assert pos >= 0, path
    prefix = raw[:pos].rstrip()
    sep = ',' if prefix.endswith('}') else ''
    addition = ',\n'.join(json.dumps(x, ensure_ascii=False, indent=2) for x in items)
    path.write_text(prefix + sep + '\n' + addition + '\n]\n', encoding='utf-8')


